'use strict';
const fs = require('fs');
const path = require('path');

// Write the entries of a parsed theme bundle ({ name, data }) into dest.
function writeEntries(dest, entries) {
  let written = 0;
  entries.forEach((entry) => {
    const target = path.join(dest, entry.name);
    fs.writeFileSync(target, entry.data);
    written += 1;
  });
  return written;
}

module.exports = { writeEntries };

'use strict';
const fs = require('fs');
const os = require('os');
const path = require('path');
const { writeEntries } = require('../lib/unpack');

test('writes_entries', () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'unpack-'));
  expect(writeEntries(dir, [{ name: 'a.css', data: 'x' }])).toBe(1);
});
